import{_ as t,o,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Reef- Performance Meeting","description":"","frontmatter":{"title":"CDS Reef- Performance Meeting","date":"2022-04-22T00:00:00.000Z","updated":"2022-04-23T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能优化","BlueStore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏编码","复制","快照","克隆","虚拟化","云计算","存储","监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/CDS_Reef_-_Performance_Meeting.md","filePath":"posts/2022/CDS_Reef_-_Performance_Meeting.md","lastUpdated":1780459816000}'),i={name:"posts/2022/CDS_Reef_-_Performance_Meeting.md"};function n(a,e,l,p,_,c){return o(),r("div",null,[...e[0]||(e[0]=[s("<p>在最近的Ceph存储系统性能会议上，团队讨论了最新的更新、问题修复以及性能优化等方面的重要议题。以下是会议的主要内容和决定：</p><ol><li><p><strong>版本发布与问题跟踪</strong>：团队正在处理Quincy和Pacific 162h版本的后续事宜，包括关闭一些不必要的Pull Request（PR），并更新了一些特定的PR。</p></li><li><p><strong>代码审查</strong>：Corey的PR经过广泛讨论，Casey和Igor已审查并认为其良好，但建议增加配置参数以在必要时恢复到旧的行为模式。</p></li><li><p><strong>性能优化</strong>：</p><ul><li>讨论了一个时间基算法的更新，旨在改善ADL分配器的性能，避免重复搜索，简化逻辑，提高可理解性。</li><li>Radik讨论了Crimson项目中的内存管理问题，提出可能的解决方案，并计划进行进一步的测试和优化。</li></ul></li><li><p><strong>文档更新</strong>：关于重写硬件文档的PR，进行了一些关于措辞的建议和讨论。</p></li><li><p><strong>关键问题解决</strong>：Corey详细描述了他们遇到的一项严重性能问题，涉及动态分片操作失败导致集群性能急剧下降的问题，并提出了解决方案。该方案将作为默认行为，但也提供了配置选项以便在出现问题时能够关闭。</p></li><li><p><strong>内存管理与性能测试</strong>：Radik讨论了Crimson项目中的内存管理问题，提出可能的解决方案，并计划进行进一步的测试和优化。</p></li></ol><p>会议还讨论了Crimson项目中的内存泄漏问题，并提出了可能的解决方案，包括使用TCMalloc作为系统分配器。此外，团队还讨论了驱动程序和固件的选择，并决定使用最新的固件版本。</p><p>会议决定将Corey的PR合并到主分支，并进行测试。同时，Radik将继续关注Crimson项目的内存管理问题，并尝试使用TCMalloc作为系统分配器。</p>",4)])])}const g=t(i,[["render",n]]);export{d as __pageData,g as default};
